import { createKnowledgeModuleInternal } from './module.js';

const knowledge = createKnowledgeModuleInternal();

export const getChunksFromQuery = knowledge.getChunksFromQuery;

export { splitMarkdown, CHUNK_OVERLAP, CHUNK_SIZE, type MarkdownChunk } from './chunker.js';
export { embedQuery, embedTexts } from './embeddings.js';
export {
  KnowledgeModuleError,
  type KnowledgeChunk,
  type KnowledgeErrorCode,
  type KnowledgeModule,
  type KnowledgeScope,
} from './module.js';
import { and, cosineDistance, desc, eq, sql } from 'drizzle-orm';
import { db as defaultDb } from '../../db/client.js';
import { documentChunks, documents, funds, portcos } from '../../db/schema.js';
import { embedQuery as defaultEmbedQuery } from './embeddings.js';

const uuidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const defaultChunkLimit = 8;
const maximumChunkLimit = 20;

export type KnowledgeScope = { fundId: string; portcoId?: string | null };

export type KnowledgeChunk = {
  chunkId: string;
  documentId: string;
  documentTitle: string;
  content: string;
  headingPath: string[];
  startLine: number | null;
  endLine: number | null;
  similarity: number;
};

export type KnowledgeErrorCode = 'invalid_input' | 'not_found';

export class KnowledgeModuleError extends Error {
  constructor(
    message: string,
    readonly code: KnowledgeErrorCode,
  ) {
    super(message);
    this.name = 'KnowledgeModuleError';
  }
}

type KnowledgeDatabase = typeof defaultDb;
type EmbedQuery = (query: string) => Promise<number[]>;

const assertUuid = (value: string, label: string) => {
  if (!uuidPattern.test(value)) {
    throw new KnowledgeModuleError(`Invalid ${label}`, 'invalid_input');
  }
};

const retrievalLimit = () => {
  const configured = Number(process.env.RETRIEVAL_LIMIT ?? defaultChunkLimit);
  if (!Number.isFinite(configured)) return defaultChunkLimit;
  return Math.max(1, Math.min(maximumChunkLimit, Math.floor(configured)));
};

const minimumSimilarity = () => {
  const configured = Number(process.env.RETRIEVAL_MIN_SIMILARITY ?? 0.25);
  return Number.isFinite(configured) ? Math.max(-1, Math.min(1, configured)) : 0.25;
};

export const createKnowledgeModuleInternal = ({
  db = defaultDb,
  embedQuery = defaultEmbedQuery,
}: {
  db?: KnowledgeDatabase;
  embedQuery?: EmbedQuery;
} = {}) => {
  const validateScope = async ({ fundId, portcoId }: KnowledgeScope) => {
    assertUuid(fundId, 'fund id');
    if (portcoId) assertUuid(portcoId, 'portco id');

    const [fund] = await db.select({ id: funds.id }).from(funds).where(eq(funds.id, fundId));
    if (!fund) throw new KnowledgeModuleError('Fund not found', 'not_found');

    if (portcoId) {
      const [portco] = await db
        .select({ id: portcos.id })
        .from(portcos)
        .where(and(eq(portcos.id, portcoId), eq(portcos.fundId, fundId)));
      if (!portco) throw new KnowledgeModuleError('Portco not found for fund', 'not_found');
    }
  };

  const getChunksFromQuery = async (
    scope: KnowledgeScope,
    query: string,
  ): Promise<KnowledgeChunk[]> => {
    const cleanQuery = query.trim();
    if (!cleanQuery) {
      throw new KnowledgeModuleError('Query is required', 'invalid_input');
    }

    await validateScope(scope);

    const queryVector = await embedQuery(cleanQuery);
    const distance = cosineDistance(documentChunks.embedding, queryVector);
    const similarity = sql<number>`(1 - (${distance}))`;
    const scopeFilter = scope.portcoId
      ? eq(documents.portcoId, scope.portcoId)
      : eq(documents.fundId, scope.fundId);

    const rows = await db
      .select({
        chunkId: documentChunks.id,
        documentId: documents.id,
        documentTitle: documents.title,
        content: documentChunks.content,
        headingPath: documentChunks.headingPath,
        startLine: documentChunks.startLine,
        endLine: documentChunks.endLine,
        similarity,
      })
      .from(documentChunks)
      .innerJoin(documents, eq(documentChunks.documentId, documents.id))
      .where(
        and(
          eq(documents.fundId, scope.fundId),
          eq(documents.status, 'ready'),
          scopeFilter,
          sql`${similarity} >= ${minimumSimilarity()}`,
        ),
      )
      .orderBy(desc(similarity), desc(documentChunks.id))
      .limit(retrievalLimit());

    return rows.map((row) => ({ ...row, similarity: Number(row.similarity) }));
  };

  return { getChunksFromQuery };
};

export type KnowledgeModule = ReturnType<typeof createKnowledgeModuleInternal>;
  db?: ChatDatabase;
  scopes?: ScopesModule;
  getChunksFromQuery?: typeof defaultGetChunksFromQuery;
  answerModel?: AnswerModel;
  createId?: () => string;
} = {}) => {
  const normalizeScope = async ({ fundId, portcoId }: ChatScope) => {
    assertUuid(fundId, 'fund id');
    if (portcoId) assertUuid(portcoId, 'portco id');
    await scopes.getScope({ fundId, portcoId });
    return { fundId, portcoId: portcoId ?? null };
  };

  const getMessages = async (chatId: string): Promise<Message[]> => {
    const rows = await db
      .select({
        id: messages.id,
        role: messages.role,
        content: messages.content,
        createdAt: messages.createdAt,
      })
      .from(messages)
      .where(eq(messages.chatId, chatId))
      .orderBy(asc(messages.createdAt), asc(messages.id));
    if (!rows.length) return [];
    const messageIds = rows.map((row) => row.id);
    const citations = await db
      .select({
        messageId: messageCitations.messageId,
        chunkId: messageCitations.chunkId,
        documentId: documentChunks.documentId,
        documentTitle: documents.title,
        headingPath: documentChunks.headingPath,
        startLine: documentChunks.startLine,
        endLine: documentChunks.endLine,
        citationOrder: messageCitations.citationOrder,
        excerpt: messageCitations.excerpt,
      })
      .from(messageCitations)
      .innerJoin(documentChunks, eq(messageCitations.chunkId, documentChunks.id))
      .innerJoin(documents, eq(documentChunks.documentId, documents.id))
      .where(inArray(messageCitations.messageId, messageIds))
      .orderBy(asc(messageCitations.citationOrder), asc(messageCitations.chunkId));
    const citationsByMessage = new Map<string, MessageCitation[]>();
    for (const citation of citations) {
      const list = citationsByMessage.get(citation.messageId) ?? [];
      list.push({
        chunkId: citation.chunkId,
        documentId: citation.documentId,
        documentTitle: citation.documentTitle,
        headingPath: citation.headingPath,
        startLine: citation.startLine,
        endLine: citation.endLine,
        citationOrder: citation.citationOrder,
        excerpt: citation.excerpt,
      });
      citationsByMessage.set(citation.messageId, list);
    }
    return rows.map((row) => ({ ...row, citations: citationsByMessage.get(row.id) ?? [] }));
  };

  const listChats = async (scope: ChatScope): Promise<ChatSummary[]> => {
    const normalized = await normalizeScope(scope);
    const scopeFilter = normalized.portcoId
      ? eq(chats.portcoId, normalized.portcoId)
      : isNull(chats.portcoId);
    return db
      .select({
        id: chats.id,
        fundId: chats.fundId,
        portcoId: chats.portcoId,
        title: chats.title,
        createdAt: chats.createdAt,
        updatedAt: chats.updatedAt,
      })
      .from(chats)
      .where(and(eq(chats.fundId, normalized.fundId), scopeFilter))
      .orderBy(desc(chats.updatedAt), desc(chats.id));
  };

  const createChat = async (input: CreateChatInput): Promise<ChatDetails> => {
    const normalized = await normalizeScope(input);
    const initialMessage = input.initialMessage.trim();
    if (!initialMessage) throw new ChatModuleError('Initial message is required', 'invalid_input');
    if (new TextEncoder().encode(initialMessage).byteLength > maxInitialMessageBytes) {
      throw new ChatModuleError('Initial message is too large', 'invalid_input');
    }
    const title = input.title?.trim() || compactTitle(initialMessage);
    if (title && title.length > maxTitleLength) {
      throw new ChatModuleError(
        `Title must be at most ${maxTitleLength} characters`,
        'invalid_input',
      );
    }
    const chatId = createId();
    const now = new Date();
    return db.transaction(async (tx) => {
      const [chat] = await tx
        .insert(chats)
        .values({ id: chatId, ...normalized, title, createdAt: now, updatedAt: now })
        .returning({
          id: chats.id,
          fundId: chats.fundId,
          portcoId: chats.portcoId,
          title: chats.title,
          createdAt: chats.createdAt,
          updatedAt: chats.updatedAt,
        });
      if (!chat) throw new Error('Chat insert returned no row');
      const [message] = await tx
        .insert(messages)
        .values({ id: createId(), chatId, role: 'user', content: initialMessage, createdAt: now })
        .returning({
          id: messages.id,
          role: messages.role,
          content: messages.content,
          createdAt: messages.createdAt,
        });
      if (!message) throw new Error('Message insert returned no row');
      return { ...chat, messages: [{ ...message, citations: [] }] };
    });
  };

  const getChat = async ({
    chatId,
    fundId,
    portcoId,
  }: { chatId: string } & ChatScope): Promise<ChatDetails> => {
    assertUuid(chatId, 'chat id');
    const normalized = await normalizeScope({ fundId, portcoId });
    const scopeFilter = normalized.portcoId
      ? eq(chats.portcoId, normalized.portcoId)
      : isNull(chats.portcoId);
    const [chat] = await db
      .select({
        id: chats.id,
        fundId: chats.fundId,
        portcoId: chats.portcoId,
        title: chats.title,
        createdAt: chats.createdAt,
