  };
  const getDocument = async (
    scope: { documentId: string } & DocumentScope,
  ): Promise<DocumentDetails> => {
    const { storageKey, metadata, ...summary } = await findDocument(scope);
    try {
      const content = new TextDecoder('utf-8', { fatal: true }).decode(
