        .update(documents)
        .set({
          status: 'ready',
          metadata: { ...document.metadata, frontmatter: parsed.frontmatter },
          errorMessage: null,
          completedAt,
          updatedAt: completedAt,
        })
        .where(eq(documents.id, documentId));
    });
  },
