                    ),
                    h2: ({ children }) => (
                      <h2 className="font-serif text-2xl font-normal">{children}</h2>
                    ),
                    h3: ({ children }) => (
                      <h3 className="font-serif text-xl font-normal">{children}</h3>
                    ),
                    a: ({ children, href }) => (
                      <a className="text-accent underline" href={href}>
                        {children}
                      </a>
